contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);

        bool reverted;
        try c.transfer(from, caddress, _tos, v) returns (bool) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(caddress.call(abi.encodeWithSelector(bytes4(keccak256("transferFrom(address,address,uint256)")), from, _tos[0], v)));
        } else {
            bool allSucceeded;
            try c.transfer(from, caddress, _tos, v) returns (bool) {
                allSucceeded = true;
            } catch {
                allSucceeded = false;
            }
            assert(!allSucceeded);
        }
    }

    receive() external payable {}
}

