    }

    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);

        bool ok;
        bytes4 id;
        bytes memory data;
        bool success;

        ok = true;
        id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        for (uint i = 0; i < _tos.length; i++) {
            data = abi.encodeWithSelector(id, from, _tos[i], v);
            (success, ) = caddress.call(data);
            if (!success) {
                ok = false;
                break;
            }
        }

        bool reverted;
        try c.transfer(from, caddress, _tos, v) returns (bool) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted == !ok);
    }

    receive() external payable {}
}

